insert into public.stays (slug,title,subtitle,excerpt,country,date_text,duration_text,price_text,cover_image,content,cta_text,status,featured,sort_order,legacy_url) values ($q$somaticky-retreat-s-ritualem-delohy-na-vysocine$q$,$q$Transformační pobyt s rituálem dělohy v ČR$q$,$q$Exkluzivní víkendový pobyt s rituály dělohy, mexickým kakaem a alchymií bylin$q$,$q$Cítíte se v poslední době přetížená, unavená? Zvu vás na pobyt, kde najdete sama sebe, klid a zbavíte se toho, co už vám neslouží.$q$,$q$Česko$q$,$q$únor a březen 2027$q$,$q$3 dny, 2 noci$q$,$q$7 200,-Kč$q$,$q$/images/legacy/2026-06-3-ohrivace.jpg$q$,$q$<div class="gallery"><img src="/images/legacy/2026-04-Mech-a-meditujici-zena-v-lese.png" alt="" /><img src="/images/legacy/2026-04-IMG_2436.jpg" alt="" /><img src="/images/legacy/2026-04-priroda.webp" alt="" /></div>
<p>Zastav se na chvíli, která může změnit víc než si myslíš! Jsou to 3 dny, během kterých:</p>
<ul>
<li>zpomalíš a <strong>nacítíš se na sebe</strong> </li>
<li><strong>uvolníš</strong> tělo i hlavu</li>
<li>spojíš se se sebou samým, se svým srdcem</li>
<li>propustíš staré zátěže</li>
<li>najdeš <strong>byliny</strong> a způsoby jak se <strong>uzdravovat</strong></li>
<li><strong>součástí pobytu je i unikátní rituál del útero, se kterým se běžně v ČR nesetkáš. Jsem druhou evropankou s iniciací od prehispánských abuel!</strong></li>
<li>ochutnáš <strong>pravé mexické kakao</strong> s jeho účinky</li>
</ul>
<p>Součástí pobytu je:</p>
<ul>
<li><strong>meditace v pohybu</strong>, techniky jak uvolnit <strong>běžný stres</strong></li>
<li><strong>meditace </strong>v klidu a tichu za pomocí <strong>pravého mexického kakaa</strong></li>
<li><strong>dva rituály del útero</strong> - původní rituál <strong>mexických šamanek</strong> (léčení ženských pohlavních orgánů a blokád v ženské linii. Tento rituál je vhodný i pro muže)</li>
<li>techniky<strong> jak se napojit na energii přírody</strong> a jak s ní pracovat</li>
<li>tradiční technika z Mexika <strong>" energetická očista vajíčkem"</strong></li>
<li>jak působí<strong> byliny</strong> na naše tělo, - <strong>intuitivní práce s bylinami</strong></li>
<li><strong>dárek pro vás</strong> -vlastní,  intuitivně namíchaný čaj a <strong>balíček produktů Serafin</strong></li>
</ul>

<h5>Chcete více informací o pobytu?</h5>
<h5>Chcete se přihlásit na pobyt?</h5>
<h5>Napište mi na tel. +420 720 680 451 Ozvu se vám!</h5>
<h2>Program:</h2>
<p>PÁTEK: <strong>Opuštění hlavy a první očištění pánevní oblasti</strong></p>
<p>17:00 – 18:00 | Příjezd a ubytování<br />Úvodní povídání a večeře<br />Seznámení, nastavení bezpečného prostoru a sdílení záměru. Teplá večeře.<br /><strong>První rituál dělohy: „Opuštění starého týdne“</strong><br /><em>Záměr:</em> <strong>Očištění od nánosů</strong> z běžného života, zklidnění nervové soustavy, naladění se sama na sebe a na své vlastní procesy.<br /><em>Praxe:</em> Poprvé vstupuješ nad sahumador. Teplo uvolní pánevní oblast a <strong>zrelaxuje celé tělo</strong>.</p>
<p>SOBOTA: <strong>Síla kakaa, lehký pohyb a hluboké uvolnění před dávným rituálem del útero</strong></p>
<p> Ranní probuzení a snídaně aktivace energie lehkým cvičením a snídaně.<br /> Dopolední <strong>rituál s pravým mexickým kakaem a meditace v pohybu venku</strong><br /><em>Přístup:</em> Ochutnáš kakao jako přírodní stimulant kardiovaskulárního systému, který okysličuje tělo a uvolňuje hormony štěstí.<br /><em>Praxe:</em> Společné pití teplého kakaa s následnou meditací v pohybu v přírodě (vědomá chůze, propojení se s elementy přírody). Uvolnění zadržovaných emocí.<br /> Oběd a odpočinek<br /> <strong>Druhý rituál Sahumación: „Cesta do hloubky a uvolnění emočních blokád“</strong><br /><em>Záměr:</em> Po dopoledním pohybu a kakau je tělo otevřené a připravené propustit hlubší psychické a <strong>psychosomatické bloky</strong> a zároveň <strong>léčit fyzické nemoci.</strong><br />Po rituálu: Opět okamžitý odchod do tepla, integrace, ticho a klid.<br /> Večeře<br /> Večerní integrace a sdílení<br />Jemné sesednutí v kruhu, prostor pro sdílení prožitků z obou rituálů a kakaa. Vedená relaxace pro hluboký spánek.</p>
<p>NEDĚLE: <strong>Alchymie ženských bylin a ukotvení</strong></p>
<p>Neděle je o integraci, získání praktických znalostí a namíchání si vlastní medicíny na doma.</p>
<p> Ranní probuzení a snídaně aktivace energie lehkým cvičením a snídaně.<br /> <strong>Bylinková alchymie: Rozpoznání ženských bylin a intuitivní čaj</strong><br /><em>Záměr:</em> Žádná esoterika, ale návrat k tradičnímu bylinkářství předků <br /><em>Praxe:</em> Představíme si klíčové ženské bylinie (např. kontryhel, řebříček, měsíček, rozmarýn, maliník) a jejich reálné účinky na ženský cyklus, dělohu a psychiku.<br />Budeš byliny poznávat skrze vůni a hmat a následně si intuitivně namícháš svůj vlastní osobní bylinný čaj, který si v krabičce odvezeš domů jako svou osobní kotvu a medicínu.<br /> Závěrečný kruh a rozloučení<br />Shrnutí víkendu, zpětná vazba, praktické rady, jak si udržet „vnitřní teplo“ v běžném životě.</p>
<p>Odjezd domů kolem 12:30.</p>
<p><em>Program je orientační a může se měnit podle aktuální situace</em></p>
