insert into public.stays (slug,title,subtitle,excerpt,country,date_text,duration_text,price_text,cover_image,content,cta_text,status,featured,sort_order,legacy_url) values ($q$mexiko-transformacni-pobyt-special$q$,$q$Mexiko – otevření vnitřní síly (SPECIÁL)$q$,$q$Transformační retreat u moře a v džungli Mexika s pradávnými Mayskými tradicemi$q$,$q$Cítíš, že potřebuješ změnu? Načerpat síly a začít léčení a životní transformaci? Speciální pobyt s rituály mayských šamanek.$q$,$q$Mexiko$q$,$q$listopad 2026$q$,$q$10 dní$q$,$q$1 550 EUR$q$,$q$/images/legacy/2026-01-oma-2.jpg$q$,$q$<div class="gallery"><img src="/images/legacy/2025-12-2b1a1d58-9f10-4247-9bcc-750f1042734e.jpg" alt="" /><img src="/images/legacy/2023-04-vychod-slunce.jpg" alt="" /><img src="/images/legacy/2026-01-oma-2.jpg" alt="" /></div>
<p>Pobyt je určen pro:</p>
<ul>
<li>pro ženy, které cítí <strong>vyčerpání</strong> nebo vnitřní odpojení</li>
<li>pro ženy, které chtějí znovu <strong>cítit své tělo</strong> a intuici</li>
<li>pro ty, které volá Mexiko, moře, džungle a ženské rituály</li>
<li>pro ženy, které jsou připravené udělat <strong>krok k sobě</strong></li>
</ul>
<p>Součástí pobytu jsou tradiční mayské rituály s místní šamankou – moudrou ženou, která nás povede při:</p>
<ul>
<li><strong>kakaový rituál</strong> ( rituál del cacao)</li>
<li>očistný <strong>temazkal</strong> ( potní chýše)</li>
<li><strong>rituál del útero</strong> (léčení ženských pohlavních orgánů a blokád v ženské linii. tento rituál je vhodný i pro muže)</li>
<li>speciální prehispánské<strong> energetické masáže</strong></li>
</ul>
<p>Pobyt probíhá na dvou místech. U<strong> moře v hotelu a v džungli ve speciálním centru</strong> určeném na retrety v souladu s <strong>mayskými tradicemi.</strong> </p>
<p><strong>Cítíte se vyčerpaní, unavení? Hledáte životní cestu? Máte chronické zdravotní problémy?Tak to je právě pro vás!</strong></p>
<p><strong>Našimi průvodkyněmi budou místní šamanky</strong>. Zrelaxujeme u moře, zapracujeme na svém fyzickém i duševním zdraví v retretovém centru, navštívíme pyramidy, památky, a také se vykoupeme v cenotech.  Síla moře nám pomůže!</p>
<h2>Recenze od mých klientů</h2>
<blockquote><p>Zájezd do Mexika s paní Anetou byl úžasný a zcela předčil mé očekávání. Velmi oceňuji individuální a trpělivý přístup paní Anety ke svým klientům. Pěkné, čisté ubytování u moře, skvělý program včetně rituálů přímo v džungli, koupání v cenotech, zajímavé výlety.  Rituál del útero a temazcal se šamankou Cristinou byl pro mě nezapomenutelný zážitek. Síla tohoto rituálu mě překvapila. Pokud chcete ve svém životě něco změnit a poznat nádhernou Mexickou kulturu, vřele doporučuji. Přála bych si se do Mexika vrátit a zažít další poznávání této země. Aneto, moc děkuji, </p><footer>Hanna</footer></blockquote><blockquote><p>Pro mne nejlepší věc byla ,že vše bylo naplánováno dopředu a já se nemusela prostě vůbec o nic starat. Zážitky které bych si sama třeba nenaordinovala přesto jsem se nebála do toho jít a byla jsem ráda. Například temazcal se šamanem Alejandrem v energii bájného Teotihuacánu!  Vřele doporučuji!
Anetina znalost španělštiny, kultury, historie a skvělých průvodců je k nezaplacení. Nic nebyl problém, vše bylo zařízené na jedničku od osobního řidiče po stravování a ubytování.
Mexiko je krásná země a definitivně stojí za návštěvu speciálně s Anetou.</p><footer>Renata</footer></blockquote><blockquote><p>Energie, kterou jsem zažila v Peru byla neskutečná. Návštěva Machu Picchu, energie hor nebo jen procházka po náměstí v Cuzcu. Vše mě naplnilo energií. Koupání v termálních lázních bylo skvělé!</p><footer>Jana</footer></blockquote><blockquote><p>Anet, za sebe můžu říct, že si mi mooooc pomohla a jsem nesmírně ráda, že jsem s Tebou nejen rituály absolvovala! Byl to neskutečně silný zážitek a upřímně uvažuji, že bych tu úžasnou energii chtěla zažít znovu!</p><footer>Radka</footer></blockquote>
<h2>Chcete více informací o pobytu?<br />Chcete se přihlásit na pobyt?<br />Napište mi na tel. +420 720 680 451 Ozvu se vám!</h2>
<h2>Program:</h2>
<p><strong>První část:</strong> <em>Retreat začíná jemně...</em><br />Ubytování v hotelu se snídaní 300 m od moře v klidné části s výhledem na moře a džungli. Tyto první dny slouží k: hlubokému uvolnění těla i mysli, aklimatizaci a zpomalení. Návratu k dechu a přítomnému okamžiku<br /><em>Moře začne rozpouštět vše, co už nepotřebuješ nést.</em></p>
<p><strong>Den 1</strong> - přílet na letiště <strong>Cancún - Mexiko</strong>. Odjezd do přímořského městečka Playa del Carmen- ubytování a první koupání v nádherném Karibském moři, noční procházka městem s množstvím restaurací, barů a zábavy.</p>
<p><strong>Den 2</strong> - ráno společná <strong>meditace u moře, uvolnění energií, léčení vodou.       </strong>Volný program. Koupání v moři, aklimatizace</p>
<p><strong>Druhá část:</strong> <em>srdce džungle a posvátný prostor retretového centra</em><br />Ubytování v kabaňách (domečcích) v tichu přírody a energii živlů</p>
<p>Čekají nás tradiční mayské rituály. <strong>Temazcal, Rituál del útero, Rituál del Cacao, meditace, energetické masáže</strong>. Celým procesem nás povede zkušená léčitelka a šamanka Cristina.</p>
<p><strong>Součástí těchto dní je lehké, výživné jídlo</strong> – 3× denně, připravené v souladu s tímto procesem.</p>
<p><strong>Den 3 - </strong>ráno společná<strong> meditace u moře spojení s vlastní léčivou energií      </strong>odpoledne přesun do<strong> nádherného retretového centra </strong>v džungli a ubytování. Večer<strong> očistný temazcal se šamanou Cristínou. </strong>Energetická<strong> práce se strachy.</strong></p>
<p><strong>Den 4 - </strong>ráno společná<strong> meditace. </strong>Odpoledne<strong> rituál del utero. </strong>Speciální rituál se šamankou na<strong> léčbu ženských nemocí. </strong>Tento rituál zároveň<strong> uvolňuje blokády celé ženské rodové linie.  Energetické masáže dle domluvy. </strong>V průběhu dne masáže a povídání se šamankou. Celé retretové centrum je jen pro nás.</p>
<p><strong>Den 5</strong> - ráno společná <strong>meditace.</strong> Odpoledne<strong> rituál del cacao</strong>. Speciální rituál se šamankou na <strong>otevření srdce a podporu přijímání sama sebe</strong>. <strong>Energetické masáže dle domluvy.</strong>  V průběhu dne masáže a povídání se šamankou. Celé retretové centrum je jen pro nás.</p>
<p><strong>Den 6</strong>- ráno společná <strong>meditace. </strong>Po snídani <strong>přesun zpět do Playa del Carmen do hotelu přímo u moře. </strong></p>
<p><strong>Třetí část: </strong><em>Návrat k lehkosti a radosti</em><strong><br /></strong>Ubytování v hotelu přímo u pláže se skvělou snídaní a lehátky hned na pláži Po hluboké práci na sobě se vrátíš k moři, kde budou pokračovat ranní meditace. Naplánujeme společně výlety na pyramidy, do nádherných cenotů, kde můžeme pokračovat s prací na sobě a budeme si užívat moře a sluníčka</p>
<p><strong>Den 6-11 - každý den ranní meditace u moře. Následně dle domluvy výlety na poznání pyramid, cenotů a krás okolí. Relexace u moře. </strong></p>
<p><strong>Den poslední</strong> transfer na letiště a odlet do Evropy</p>
<p>Celou dobu budu s vámi a budeme společně pracovat na celkové <strong>harmonizaci vašeho těla, vaší psychiky</strong>. Práce bude společná i individuální, vždy podle vašich potřeb. <strong>Vše je dobrovolné. </strong></p>
<p><em>Transformační pobyt je jen pro 6 osob! </em></p>
<p><strong>Jaké rituály nás čekají?</strong></p>
<p><strong>Všechny rituály povede místní šamanka!</strong></p>
<p>rituál zvaný <strong>"ceremonie utery"</strong>. Rituál určený pro ženy každého věku. Používá se při léčení problémů s menstruací, neplodnosti, myomů, cyst, PCOS, klimakteria, ženského psychického zdraví... Více <a href="https://anetabenediktova.cz/ritual-del-utero-lecba-zenskeho-tela-i-duse/">zde</a></p>
<p><strong>cacaový rituál</strong> - spojení se základními živly, elementy. Léčení psychického a fyzického zdraví. Více <a href="https://anetabenediktova.cz/psychologie-matky-prirody/">zde</a></p>
<p><strong>temazcal</strong> - základní očistná ceremonie . Potní chýše. více <a href="https://anetabenediktova.cz/temazcal-ocista-tela-a-duse/">zde</a></p>
<p><strong>speciální energetická prehispánská masáž</strong></p>
<p><strong>Co můžete zažít navíc?</strong></p>
<p>Krásné <strong>archeologické zóny</strong>: Chicen Itzá, Izamal, Cobá, Tulum....</p>
<p><strong>Koupání</strong> v moři a v cenotech</p>
<p>Plavání s <strong>želvami</strong>, pozorování delfínů a jiné vodní "radovánky"</p>
<p><em>Program je orientační a může se měnit podle aktuální situace</em></p>
