insert into public.stays (slug,title,subtitle,excerpt,country,date_text,duration_text,price_text,cover_image,content,cta_text,status,featured,sort_order,legacy_url) values ($q$mexiko-pro-zeny-ritualy-pro-zenske-zdravi$q$,$q$Mexiko "nejen" pro ženy$q$,$q$Speciální kurz s poznáním i s rituály - s cacaovým rituálem, rituálem utery a dalšími.$q$,$q$Speciální kurz s poznáním i s rituály - s cacaovým rituálem, rituálem utery a dalšími.$q$,$q$Mexiko$q$,$q$9.10. - 19.10.2025$q$,$q$10 dní$q$,$q$25 000 Kč nyní sleva 10%$q$,$q$/images/legacy/2024-04-IMG_9335.jpg$q$,$q$<div class="gallery"><img src="/images/legacy/2024-04-IMG_9335.jpg" alt="" /><img src="/images/legacy/2023-04-vychod-slunce.jpg" alt="" /></div>
<p><strong>Cítíte se vyčerpaná, unavená? Hledáte životní cestu? Máte problémy s menstruací, neplodnosti, myomy, cysty, PCOS, klimakterium, s vyčerpaností? Tak to je právě pro vás! </strong></p>
<p>Najdeme cestu do hloubky ženství, do míst, kde můžeš znovu najít svou sílu, nechat odejít bolesti a zranění. Je to láskyplný transformační pobyt, který využívá znalosti a tradice mayských rituálů. Našimi průvodkyněmi budou místní šamanky. Také zrelaxujeme u moře a navštívíme pyramidy a památky.</p>
<p><strong>Zažijte regeneraci energie ve vás! Restart vaší energie, celkovou harmonizaci a omlazení!</strong></p>
<p><strong> Při rituálech nás bude provázet místní šamanka.</strong></p>
<p><strong>Kurz je nejen pro ženy. </strong>I když jeden rituál se specializuje na ženské zdraví, účastnit se všech rituálů mohou i muži, je to i pro ně velmi prospěšné. </p>

