insert into public.stays (slug,title,subtitle,excerpt,country,date_text,duration_text,price_text,cover_image,content,cta_text,status,featured,sort_order,legacy_url) values ($q$mexiko-pro-zeny-ceremonie-pro-zenske-zdravi$q$,$q$Mexiko pro ženy - ceremonie pro ženské zdraví$q$,$q$speciální pobyt pro ženy s ceremoniemi na ženské zdraví$q$,$q$speciální pobyt pro ženy s ceremoniemi na ženské zdraví$q$,$q$Mexiko$q$,$q$$q$,$q$$q$,$q$$q$,$q$/images/legacy/2024-04-a0a5b740-411f-4041-8431-5483f9b6e263.jpg$q$,$q$<div class="gallery"><img src="/images/legacy/2024-04-a0a5b740-411f-4041-8431-5483f9b6e263.jpg" alt="" /><img src="/images/legacy/2023-06-Mexiko-kakaovy-ritual-1.jpg" alt="" /><img src="/images/legacy/2024-04-IMG_9330.jpg" alt="" /></div>
<p><strong>Mexiko to je slunce, nádherné moře, skvělé jídlo, magické pyramidy, cenoty a zejména tradiční ceremonie a léčení. </strong>To vám potvrdí bezpočet lidí, kteří se mnou tuto nádhernou zemi navštívilo.</p>
<p><em>Nejde o to jezdit dlouhé vzdálenosti po obrovské zemi zvané Mexiko. Jde o to, vychutnat si její energii na jednom, dvou nebo třech místech. Poznat to, co nabízí a prožít to.</em></p>
<p><strong>Zažijte harmonizaci a regeneraci ženské energie ve vás!</strong></p>
<p><strong>Co vás čeká?</strong></p>
<ul>
<li><strong>rituál zvaný "ceremonie utery". Rituál určený pro ženy každého věku. </strong>Používá se při léčení problémů<strong> s menstruací, neplodnosti, myomů, cyst, PCOS, klimakteria, ženského psychického zdraví... <a href="https://anetabenediktova.cz/ritual-del-utero-lecba-zenskeho-tela-i-duse/">Více zde</a></strong></li>
<li><strong><a href="https://anetabenediktova.cz/psychologie-matky-prirody/">cacaový rituál</a> - </strong>spojení se základními živly, elementy. Léčení psychického a fyzického zdraví</li>
<li><a href="https://anetabenediktova.cz/temazcal-ocista-tela-a-duse/"><strong>temazcal</strong></a> - základní očistná ceremonie</li>
<li><strong>meditace</strong> - meditace zaměřené na ženskou energii</li>
<li><strong>jóga</strong> - v případě zájmu</li>
</ul>
<p>Co můžete zažít navíc?</p>
<ul>
<li><strong>Krásné archeologické zóny: Chicen Itzá, Izamal, Cobá, Tulum....</strong></li>
<li><strong>Koupání v moři a v cenotech</strong></li>
<li><strong>Plavání s želvami, pozorování delfínů a jiné vodní "radovánky"</strong></li>
</ul>
<p><b>Ubytování: </b></p>
<p>Hotel apartmánového typu s vlastní zahradou v klidné části na okraji Playa del Carmen 250 m od moře. Do rušné části městečka lze dojít po pěší stezce za 10 minut.</p>
<p>Ubytování je zajištěné ve dvoulůžkových pokojích vybavených oddělenými postelemi, malou kuchyňkou, koupelnou, toaletními potřebami, ručníky. Ubytování je se snídaní</p>
<p><strong>Celou dobu budu vaším průvodcem.</strong></p>

<h2>Chcete více informací? Dejte mi vědět</h2>
<p>Pro vaše případné dotazy jsem vám plně k dispozici na whatsappu: +420720680451 nebo emailu: anetabenediktova@seznam.cz. Napsat mi můžete i přes formulář níže.</p>$q$,$q$Mám zájem$q$,$q$draft$q$,false,100,$q$https://anetabenediktova.cz/sluzby/cestovani-s-anetou/mexiko-pro-zeny-ceremonie-pro-zenske-zdravi/$q$) on conflict (slug) do nothing;
insert into public.stays (slug,title,subtitle,excerpt,country,date_text,duration_text,price_text,cover_image,content,cta_text,status,featured,sort_order,legacy_url) values ($q$mexiko-relaxace-meditace-cestovani$q$,$q$Mexiko, Guatemala a Belize. Poznání, relaxace a přírodní rituály$q$,$q$unikátní zájezd zaměřený na restart těla i ducha, na načerpání sil i poznání.$q$,$q$unikátní zájezd zaměřený na restart těla i ducha, na načerpání sil i poznání.$q$,$q$Mexiko$q$,$q$$q$,$q$$q$,$q$$q$,$q$/images/legacy/2023-06-viktor-v-dzungli-1.jpg$q$,$q$<figure><img src="/images/legacy/2023-06-viktor-v-dzungli-1.jpg" alt="" /></figure>
<p><strong>Zažijte unikátní zájezd JINAK!</strong>  Mexiko, Guatemala, Belize, a to vše v místech s dávnou historií v blízkosti <strong>pyramid, džungle </strong>v doprovodu místních šamanů a indiánů.<strong> V Mexiku i Guatemale</strong> najdete nádherné pyramidy a archeologické zóny, mystická místa plná energie, džungli i pouště. Mexiko i <strong>Belize</strong> má nádherné a teplé tyrkysové moře, bělostné pláže a plno slunce.</p>
<p>Pojeďte se mnou na zajímavou cestu do 3 zemí plnou poznání dávných kultur. Budeme společně <strong>stoupat na pyramidy, poznávat kulturu</strong> a zemi, <strong>ochutnávat skvělé jídlo</strong> a kdo bude chtít tak praktikovat <strong>jednoduché relaxační techniky. </strong></p>
<p>Potkáme se s místními <strong>indiány, zažijeme cacaový rituál i očistný temazcal, projdeme se džunglí a vykoupeme se v nádherných vodopádech i moři</strong>.  Samozřejmě, pokud budete chtít.... <strong>vše je dobrovolné!</strong></p>
<p><strong>Relaxační techniky jsou jednoduché za pomocí dechu. Je to doprovodný program jen pro ty, kteří chtějí!</strong></p>
<p><strong>Termín:  18.2. - 1.3.2024</strong></p>
<p>Líbí se vám? Vyplňte nezávaznou přihlášku v dolní části stránky a já se vám ozvu, nebo mě můžete přímo<strong> kontaktovat na tel. +420 720 680 451, ideálně přes Whatsapp</strong></p>
<p> Těším se na společné zážitky!</p>
<p><a href="https://anetabenediktova.cz/mexiko-guatemala-belize-poznani-relaxace-a-mistni-samane/">Kompletní program a cena zájezdu</a></p>
<h2>Chcete více informací? Dejte mi vědět</h2>$q$,$q$Mám zájem$q$,$q$draft$q$,false,100,$q$https://anetabenediktova.cz/sluzby/cestovani-s-anetou/mexiko-relaxace-meditace-cestovani/$q$) on conflict (slug) do nothing;
insert into public.stays (slug,title,subtitle,excerpt,country,date_text,duration_text,price_text,cover_image,content,cta_text,status,featured,sort_order,legacy_url) values ($q$mexiko-transformacni-pobyt-pro-zeny$q$,$q$Mexiko-transformační pobyt nejen pro ženy$q$,$q$zaměřeno na osobní růst, léčení, napojení na přírodu a pradávné mayské tradice.$q$,$q$zaměřeno na osobní růst, léčení, napojení na přírodu a pradávné mayské tradice.$q$,$q$Mexiko$q$,$q$6 - 15.8.2026$q$,$q$10 dní$q$,$q$900 euro$q$,$q$/images/legacy/2024-04-IMG_9335.jpg$q$,$q$<div class="gallery"><img src="/images/legacy/2024-04-IMG_9335.jpg" alt="" /><img src="/images/legacy/2023-04-vychod-slunce.jpg" alt="" /><img src="/images/legacy/2021-02-5da8f2d5-297a-427d-8658-671e817c1e51.jpg" alt="" /></div>
<p>Pobyt je určen pro všechny, kteří chtějí:</p>
<ul>
<li>najít svou životní cestu</li>
<li>zbavit se vnitřních bloků a strachů</li>
<li>léčit své nemoci a traumata přirozenou cestou</li>
<li>načerpat sílu a energii z přírody a dávných mayských tradic</li>
</ul>
<p>Součástí pobytu jsou tradiční mayské rituály s místní šamankou – moudrou ženou, která nás povede při:</p>
<ul>
<li>kakaový rituál ( rituál del cacao)</li>
<li>očistný temazkal ( potní chýše)</li>
<li>rituál del útero (léčení ženských pohlavních orgánů a blokád v ženské linii. tento rituál je vhodný i pro muže)</li>
<li>energetická očista</li>
</ul>
<p>Pobyty probíhají v silových místech a v souladu s <strong>mayskými tradicemi.</strong> </p>
<p>Cítíte se vyčerpaní, unavení? Hledáte životní cestu? Máte chronické zdravotní problémy?Tak to je právě pro vás!</p>
<p><strong>Našimi průvodkyněmi budou místní šamanky</strong>. Zrelaxujeme u moře a navštívíme pyramidy, památky, a také se vykoupeme v cenotech.  Síla moře nám pomůže!</p>
<h2>Recenze od mých klientů</h2>
<blockquote><p>Zájezd do Mexika s paní Anetou byl úžasný a zcela předčil mé očekávání. Velmi oceňuji individuální a trpělivý přístup paní Anety ke svým klientům. Pěkné, čisté ubytování u moře, skvělý program včetně rituálů přímo v džungli, koupání v cenotech, zajímavé výlety.  Rituál del útero a temazcal se šamankou Cristinou byl pro mě nezapomenutelný zážitek. Síla tohoto rituálu mě překvapila. Pokud chcete ve svém životě něco změnit a poznat nádhernou Mexickou kulturu, vřele doporučuji. Přála bych si se do Mexika vrátit a zažít další poznávání této země. Aneto, moc děkuji, </p><footer>Hanna</footer></blockquote><blockquote><p>Pro mne nejlepší věc byla ,že vše bylo naplánováno dopředu a já se nemusela prostě vůbec o nic starat. Zážitky které bych si sama třeba nenaordinovala přesto jsem se nebála do toho jít a byla jsem ráda. Například temazcal se šamanem Alejandrem v energii bájného Teotihuacánu!  Vřele doporučuji!
Anetina znalost španělštiny, kultury, historie a skvělých průvodců je k nezaplacení. Nic nebyl problém, vše bylo zařízené na jedničku od osobního řidiče po stravování a ubytování.
Mexiko je krásná země a definitivně stojí za návštěvu speciálně s Anetou.</p><footer>Renata</footer></blockquote><blockquote><p>Energie, kterou jsem zažila v Peru byla neskutečná. Návštěva Machu Picchu, energie hor nebo jen procházka po náměstí v Cuzcu. Vše mě naplnilo energií. Koupání v termálních lázních bylo skvělé!</p><footer>Jana</footer></blockquote><blockquote><p>Anet, za sebe můžu říct, že si mi mooooc pomohla a jsem nesmírně ráda, že jsem s Tebou nejen rituály absolvovala! Byl to neskutečně silný zážitek a upřímně uvažuji, že bych tu úžasnou energii chtěla zažít znovu!</p><footer>Radka</footer></blockquote>
<h2>Chcete více informací o zájezdu? Dejte mi na sebe číslo a já se vám obratem ozvu. Je to nezávazné.</h2>
<h2>Program:</h2>
<p><strong>6.8.</strong> - přílet na letiště <strong>Cancún - Mexiko</strong>. Odjezd do přímořského městečka Playa del Carmen- ubytování a první koupání v nádherném Karibském moři, noční procházka městem s množstvím restaurací, barů a zábavy.</p>
<p><strong>7.8.</strong> - ráno společná <strong>meditace u moře, uvolnění energií, léčení vodou.       </strong>odpoledne<strong> očistný temazcal (potní chýše) se šamankou mayské cesty Cristínou</strong></p>
<p><strong>8.8. - </strong>ráno společná<strong> meditace u moře , propuštění starých strachů.     </strong>V průběhu dne<strong> "africké tance" - harmonizace a uvolnění energií</strong></p>
<p><strong>9.8. - </strong>ráno společná<strong> meditace u moře spojení s vlastní léčivou energií      </strong>potom<strong> léčivý "rituál del utero" se šamankou mayské cesty Cristínou</strong></p>
<p><strong>10.8. - </strong>ráno společná<strong> meditace u moře , dokončení duchovní práce z předešlého dne.  </strong>Volný den na relaxaci u moře, nákupy nebo výlet. <strong>Možnost irisdiagnostiky a individuální terapie se mnou.</strong></p>
<p><strong>11.8.</strong> - celodenní výlet na archeologickou zónu s nejznámější pyramidou <strong>Chichen Itzá</strong>, koupání v cenotech , prohlídka koloniálního městečka Valladolid - vše dobrovolné</p>
<p><strong>12.8.</strong> - ráno společná <strong>meditace u moře zaměřená na uvolnění pocitů křivd</strong>    Volný den na relaxaci u moře, nákupy nebo výlet. V případě zájmu <strong> energetická masáž a mayská očista a léčení se šamankou Gis. Také je možné objednat čtení karet a mayského horoskopu.</strong></p>
<p><strong>13.8. - </strong>ráno společná<strong> meditace u moře zaměřená na aktivaci vniřní energie. </strong>Odpoledne<strong> "rituál del cacao" se šamankou mayské cesty Cristínou</strong></p>
<p><strong>14.8. - </strong>ráno společná<strong> meditace u moře zaměřená vděčnost.</strong> Volný den na relaxaci u moře, nákupy nebo výlet</p>
<p><strong>15.8.</strong> transfer na letiště a odlet do Evropy</p>
<p>Celou dobu budu s vámi a budeme společně pracovat na celkové <strong>harmonizaci vašeho těla, vaší psychiky</strong>. Práce bude společná i individuální, vždy podle vašich potřeb. </p>
<p><strong>Vše je dobrovolné. Můžete si jen v klidu užít relaxaci u moře a poznávání</strong></p>
<p><em>Transformační pobyt je jen pro 8 osob, tak abych se vám mohla <strong>věnovat individuálně,</strong> abychom mohly společně prožít to nejlepší pro vás.</em></p>
<p><strong>Jaké rituály nás čekají?</strong></p>
<p><strong>Všechny rituály povede místní šamanka!</strong></p>
<p>rituál zvaný <strong>"ceremonie utery"</strong>. Rituál určený pro ženy každého věku. Používá se při léčení problémů s menstruací, neplodnosti, myomů, cyst, PCOS, klimakteria, ženského psychického zdraví... Více <a href="https://anetabenediktova.cz/ritual-del-utero-lecba-zenskeho-tela-i-duse/">zde</a></p>
<p><strong>cacaový rituál</strong> - spojení se základními živly, elementy. Léčení psychického a fyzického zdraví. Více <a href="https://anetabenediktova.cz/psychologie-matky-prirody/">zde</a></p>
<p><strong>temazcal</strong> - základní očistná ceremonie . Potní chýše. více <a href="https://anetabenediktova.cz/temazcal-ocista-tela-a-duse/">zde</a></p>
<p><strong>Co můžete zažít navíc?</strong></p>
<p>Krásné <strong>archeologické zóny</strong>: Chicen Itzá, Izamal, Cobá, Tulum....</p>
<p><strong>Koupání</strong> v moři a v cenotech</p>
<p>Plavání s <strong>želvami</strong>, pozorování delfínů a jiné vodní "radovánky"</p>
<p><em>Program je orientační a může se měnit podle aktuální situace</em></p>
