insert into public.stays (slug,title,subtitle,excerpt,country,date_text,duration_text,price_text,cover_image,content,cta_text,status,featured,sort_order,legacy_url) values ($q$navrat-k-sobe-transformacni-vikend-na-vysocine-v-cr$q$,$q$NÁVRAT K SOBĚ transformační víkend Vysočina v ČR$q$,$q$Transformační víkend s meditací, přírodou, bylinami a rituálem del útero$q$,$q$Transformační víkend s meditací, přírodou, bylinami a rituálem del útero$q$,$q$Česko$q$,$q$25-28.9.2026$q$,$q$4 dny, 3 noci$q$,$q$8 900,-Kč$q$,$q$/images/legacy/2026-04-Mech-a-meditujici-zena-v-lese.png$q$,$q$<div class="gallery"><img src="/images/legacy/2026-04-Mech-a-meditujici-zena-v-lese.png" alt="" /><img src="/images/legacy/2026-04-IMG_2436.jpg" alt="" /><img src="/images/legacy/2026-04-priroda.webp" alt="" /></div>
<p>Zastav se na chvíli, která může změnit víc než si myslíš! Jsou to 4 dny, během kterých:</p>
<ul>
<li>zpomalíš a <strong>nacítíš se na sebe</strong> </li>
<li><strong>uvolníš</strong> tělo i hlavu</li>
<li>spojíš se s <strong>přírodou</strong> a sebou samým</li>
<li>naučíš se <strong>techniky na uvolnění těla i mysli</strong></li>
<li>najdeš <strong>byliny</strong> a způsoby jak se <strong>uzdravovat</strong></li>
<li>součástí pobytu je i <strong>unikátní rituál del útero</strong>, se kterým se běžně v ČR nesetkáš.</li>
</ul>
<p>Součástí pobytu je:</p>
<ul>
<li><strong>meditace v pohybu</strong>, techniky jak uvolnit <strong>běžný stres</strong></li>
<li><strong>meditace v klidu a tichu</strong> a techniky jak pracovat se strachem a vnitřním dítětem. Odpuštění.</li>
<li><strong>rituál del útero</strong> - původní rituál <strong>mexických šamanek</strong> (léčení ženských pohlavních orgánů a blokád v ženské linii. Tento rituál je vhodný i pro muže)</li>
<li>techniky<strong> jak se napojit na energii přírody</strong> a jak s ní pracovat</li>
<li>tradiční technika z Mexika <strong>" energetická očista vajíčkem"</strong></li>
<li><strong>jak působí byliny</strong> na naše tělo, na hormonální a nervový systém</li>
<li><strong>dárek pro vás</strong> -vlastní,  intuitivně namíchaný čaj a <strong>balíček produktů Serafin</strong></li>
</ul>

<h2>Chcete více informací o pobytu? Dejte mi na sebe číslo a já se vám obratem ozvu. Je to nezávazné.</h2>
<h2>Program:</h2>
<p><strong>Den první (pátek)</strong> </p>
<p>příjezd do meditačního centra umístěného v přírodě.  <strong>Ubytování</strong> a večer první povídání - <strong>co to je stres, co je strach jak s nimi pracovat - praktické tipy. </strong></p>
<p><strong>Druhý den (sobota)</strong> </p>
<p>tento den budeme věnovat <strong>uvolněním a meditacím jak v pohybu, tak i v klidu</strong>. Naučíme se co je "ušlechtilé mlčení" a jak <strong>být sám v sobě</strong> a naučit se <strong>vnímat své tělo</strong>.</p>
<p>Budeme pracovat s technikami <strong>jak na svoji mysl,</strong> jak <strong>propustit své strachy </strong>a s jak se napojovat na <strong>energii přírody</strong>.</p>
<p><strong>Bude probíhat hluboké léčení na buněčné úrovni. </strong></p>
<p><strong>Třetí den (neděle) </strong></p>
<p>tento den každý <strong>individuálně zažije "rituál del útero"</strong> . Jemný, ale zároveň silný rituál, který pracuje s <strong>energiemi v pánevní oblasti a uvolňuje blokády rodových linií</strong>. Je to původní rituál <strong>mexických šamanek</strong>. Dostala jsem povolení jej praktikovat.</p>
<p>Tento den budeme také <strong>pracovat s bylinami</strong>. Naučíme se jak a na co působí a jak si intuitivně udělat svůj čaj.</p>
<p>Naučíme se také tradiční <strong>energetickou "očistu vajíčkem". </strong></p>
<p><strong>Čtvrtý den (sváteční pondělí)</strong> </p>
<p>tento den postupně zakončíme pobyt společnou meditací a rozloučením. </p>
<p><em>Program je orientační a může se měnit podle aktuální situace</em></p>
